# Builds infosys-interview/data/sql.js. Every output below is produced by running the query on SQLite.
import json, sqlite3, os
schema = [
 ('departments', ['dept_id', 'dept_name', 'city'], [(10,'Engineering','Bengaluru'),(20,'Sales','Mumbai'),(30,'HR','Pune'),(40,'Finance','Chennai')]),
 ('employees', ['emp_id','name','dept_id','salary','manager_id','hire_year'], [
   (1,'Asha',10,90000,None,2015),(2,'Ravi',10,75000,1,2018),(3,'Meena',10,75000,1,2019),(4,'Karan',20,60000,None,2016),
   (5,'Divya',20,55000,4,2020),(6,'Sanjay',20,48000,4,2021),(7,'Neha',30,52000,None,2017),(8,'Imran',30,45000,7,2022),
   (9,'Pooja',10,82000,1,2017),(10,'Vikram',None,40000,None,2023)]),
 ('projects', ['proj_id','proj_name','dept_id'], [(101,'Portal',10),(102,'CRM',20),(103,'Payroll',30),(104,'Audit',40)]),
 ('assignments', ['emp_id','proj_id','hours'], [(1,101,120),(2,101,200),(3,101,150),(9,101,90),(4,102,100),(5,102,160),(6,102,80),(7,103,140),(8,103,60),(2,102,40)]),
]
B, M, A = 'basic', 'medium', 'adv'
items = [
(B,'Show all employees with their salary, highest salary first.',"SELECT name, salary FROM employees ORDER BY salary DESC;",'`ORDER BY ... DESC` sorts descending. The default is ascending (`ASC`). Two people with the same salary may appear in either order unless you add a second sort key.'),
(B,'List the distinct hire years.',"SELECT DISTINCT hire_year FROM employees ORDER BY hire_year;",'`DISTINCT` removes duplicate rows from the result.'),
(B,'Find employees whose salary is between 50000 and 80000 and who are in department 10 or 20.',"SELECT name, dept_id, salary FROM employees\nWHERE salary BETWEEN 50000 AND 80000 AND dept_id IN (10, 20);",'`BETWEEN` is inclusive on both ends. `IN` is a shorter way to write several `OR` conditions. Vikram has no department (NULL), so he can never match `IN`.'),
(B,'Find employees whose name starts with A or ends with a.',"SELECT name FROM employees WHERE name LIKE 'A%' OR name LIKE '%a';",'`%` matches any number of characters and `_` matches exactly one. In SQLite, LIKE is case-insensitive for plain letters; in some databases it is case-sensitive.'),
(B,'Find employees who have no department.',"SELECT name FROM employees WHERE dept_id IS NULL;",'Comparing with NULL using `=` never works, because NULL means "unknown". Always use `IS NULL` or `IS NOT NULL`.'),
(B,'Count the employees and show the total, average, minimum and maximum salary.',"SELECT COUNT(*) AS total, SUM(salary) AS payroll, ROUND(AVG(salary), 2) AS avg_salary,\n       MIN(salary) AS lowest, MAX(salary) AS highest\nFROM employees;",'Aggregate functions collapse many rows into one. `COUNT(*)` counts rows; `COUNT(column)` ignores NULLs.'),
(B,'Show the number of employees and the average salary in each department.',"SELECT dept_id, COUNT(*) AS emp_count, ROUND(AVG(salary), 1) AS avg_salary\nFROM employees\nGROUP BY dept_id\nORDER BY dept_id;",'`GROUP BY` makes one group per department. Employees with a NULL department form a group of their own.'),
(B,'Show departments that have more than 2 employees.',"SELECT dept_id, COUNT(*) AS emp_count\nFROM employees\nGROUP BY dept_id\nHAVING COUNT(*) > 2;",'`WHERE` filters rows **before** grouping; `HAVING` filters groups **after** aggregation. You cannot use `COUNT(*)` in a WHERE clause.'),
(B,'Show the 3 highest paid employees, then the next 3 (page 2).',"SELECT name, salary FROM employees ORDER BY salary DESC LIMIT 3;\n-- page 2: ... ORDER BY salary DESC LIMIT 3 OFFSET 3;",'`LIMIT n` returns n rows, `OFFSET k` skips k rows first. In SQL Server use `TOP 3` or `OFFSET ... FETCH`; in Oracle `FETCH FIRST 3 ROWS ONLY`.'),
(B,'Show each employee with a salary grade using CASE.',"SELECT name, salary,\n  CASE WHEN salary >= 80000 THEN 'High'\n       WHEN salary >= 50000 THEN 'Medium'\n       ELSE 'Low' END AS grade\nFROM employees ORDER BY emp_id;",'`CASE` is the SQL if-else. Conditions are checked top to bottom and the first match wins.'),
(M,'Show each employee with the name of their department (INNER JOIN).',"SELECT e.name, d.dept_name\nFROM employees e\nINNER JOIN departments d ON e.dept_id = d.dept_id\nORDER BY e.emp_id;",'An inner join returns only rows that match in both tables. Vikram (no department) does not appear.'),
(M,'Show all employees including those without a department (LEFT JOIN).',"SELECT e.name, d.dept_name\nFROM employees e\nLEFT JOIN departments d ON e.dept_id = d.dept_id\nORDER BY e.emp_id;",'A left join keeps **every** row of the left table and fills NULL where the right table has no match.'),
(M,'Find departments that have no employees.',"SELECT d.dept_name\nFROM departments d\nLEFT JOIN employees e ON e.dept_id = d.dept_id\nWHERE e.emp_id IS NULL;",'The classic **anti-join**: left join, then keep rows where the right side is NULL. `NOT EXISTS` and `NOT IN` give the same result (be careful: `NOT IN` returns nothing if the subquery contains a NULL).'),
(M,'Show every employee together with their manager\'s name (self join).',"SELECT e.name AS employee, m.name AS manager\nFROM employees e\nLEFT JOIN employees m ON e.manager_id = m.emp_id\nORDER BY e.emp_id;",'The same table is used twice under different aliases. The top-level people have a NULL manager.'),
(M,'Find employees who earn more than their manager.',"SELECT e.name, e.salary, m.name AS manager, m.salary AS manager_salary\nFROM employees e\nJOIN employees m ON e.manager_id = m.emp_id\nWHERE e.salary > m.salary;",'The result is empty: nobody earns more than their manager in this data. An empty result is a valid answer, and the query is still correct.'),
(M,'Find the employee with the highest salary using a subquery.',"SELECT name, salary FROM employees\nWHERE salary = (SELECT MAX(salary) FROM employees);",'The inner query runs first and returns one value, then the outer query filters with it. Using this form (not `ORDER BY ... LIMIT 1`) correctly returns **all** employees tied for the top salary.'),
(M,'Find the second highest salary (with other ways in the notes).',"-- 1. Subquery\nSELECT MAX(salary) AS second_highest\nFROM employees\nWHERE salary < (SELECT MAX(salary) FROM employees);",'Other ways: `SELECT DISTINCT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET 1;` or `DENSE_RANK()` and pick rank 2. Replace 1 with N-1 in the OFFSET form for the Nth highest. The `DISTINCT` matters: two people earn 75000.'),
(M,'Find the Nth highest salary using DENSE_RANK (here N = 3).',"SELECT salary FROM (\n  SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS rnk\n  FROM employees\n) t\nWHERE rnk = 3\nGROUP BY salary;",'`DENSE_RANK` gives tied values the same rank and does **not** skip numbers (`RANK` skips). Salaries 90000, 82000, 75000 are ranks 1, 2, 3.'),
(M,'Find employees who earn more than the average salary of their own department (correlated subquery).',"SELECT e.name, e.dept_id, e.salary\nFROM employees e\nWHERE e.salary > (SELECT AVG(salary) FROM employees x WHERE x.dept_id = e.dept_id)\nORDER BY e.emp_id;",'A **correlated subquery** refers to the outer row (`e.dept_id`), so it is evaluated once per outer row. Vikram has no department, so his comparison is with NULL and he is excluded.'),
(M,'Show the highest paid employee in each department.',"SELECT d.dept_name, e.name, e.salary\nFROM employees e\nJOIN departments d ON d.dept_id = e.dept_id\nWHERE e.salary = (SELECT MAX(salary) FROM employees WHERE dept_id = e.dept_id)\nORDER BY d.dept_id;",'Joining on a group maximum is a very common interview pattern. A window function (`ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC)`) is the alternative.'),
(M,'Find salaries that appear more than once (detect duplicates).',"SELECT salary, COUNT(*) AS times\nFROM employees\nGROUP BY salary\nHAVING COUNT(*) > 1;",'Group by the column you suspect has duplicates and keep groups with a count above 1. To **delete** duplicates but keep one row, delete rows whose id is not the `MIN(id)` of each group.'),
(M,'Show total project hours per department using multiple joins.',"SELECT d.dept_name, SUM(a.hours) AS total_hours\nFROM assignments a\nJOIN projects p ON p.proj_id = a.proj_id\nJOIN departments d ON d.dept_id = p.dept_id\nGROUP BY d.dept_name\nORDER BY total_hours DESC;",'Follow the foreign keys: assignments -> projects -> departments. The Finance department has a project but nobody is assigned, so it does not appear in an inner join.'),
(M,'List employees who are assigned to more than one project.',"SELECT e.name, COUNT(*) AS projects\nFROM assignments a\nJOIN employees e ON e.emp_id = a.emp_id\nGROUP BY e.emp_id, e.name\nHAVING COUNT(*) > 1;",'Group by the employee, then use HAVING on the count.'),
(M,'Find employees who are not assigned to any project (NOT EXISTS).',"SELECT name FROM employees e\nWHERE NOT EXISTS (SELECT 1 FROM assignments a WHERE a.emp_id = e.emp_id);",'`EXISTS` stops at the first matching row, so it is often faster than `IN` for large subqueries. Only Vikram has no assignment.'),
(M,'Combine two result sets: names of managers and names of employees in department 30 (UNION).',"SELECT name FROM employees WHERE emp_id IN (SELECT manager_id FROM employees WHERE manager_id IS NOT NULL)\nUNION\nSELECT name FROM employees WHERE dept_id = 30\nORDER BY name;",'`UNION` removes duplicates (Neha is in both sets); `UNION ALL` keeps them and is faster. Both queries must return the same number of columns with compatible types.'),
(A,'Rank employees by salary inside each department with RANK and ROW_NUMBER.',"SELECT dept_id, name, salary,\n  RANK() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS rnk,\n  ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC, emp_id) AS rn\nFROM employees WHERE dept_id IS NOT NULL\nORDER BY dept_id, rn;",'`PARTITION BY` restarts the numbering for each department. Ravi and Meena tie at 75000, so `RANK` gives both rank 3 (and the next rank would be 5), while `ROW_NUMBER` always gives unique numbers (the second ORDER BY key breaks the tie).'),
(A,'Top 2 earners from each department.',"SELECT * FROM (\n  SELECT dept_id, name, salary,\n         ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC, emp_id) AS rn\n  FROM employees WHERE dept_id IS NOT NULL\n) t\nWHERE rn <= 2\nORDER BY dept_id, rn;",'You cannot use a window function directly in `WHERE`, so wrap it in a subquery (or CTE) and filter the rank outside.'),
(A,'Running total of salary ordered by hire year (and a CTE).',"WITH ordered AS (\n  SELECT emp_id, name, hire_year, salary FROM employees\n)\nSELECT name, hire_year, salary,\n       SUM(salary) OVER (ORDER BY hire_year, emp_id) AS running_total\nFROM ordered ORDER BY hire_year, emp_id;",'`SUM() OVER (ORDER BY ...)` accumulates row by row. A **CTE** (`WITH ... AS`) names a subquery to keep the main query readable.'),
(A,'Compare each employee salary with the previous hire (LAG) and the department average.',"SELECT name, hire_year, salary,\n  LAG(salary) OVER (ORDER BY hire_year, emp_id) AS prev_salary,\n  ROUND(AVG(salary) OVER (PARTITION BY dept_id), 0) AS dept_avg\nFROM employees ORDER BY hire_year, emp_id;",'`LAG` looks at the previous row (`LEAD` the next one) without a self join. `AVG() OVER (PARTITION BY ...)` shows the group average on every row without collapsing rows.'),
(A,'Managers and the number of people reporting to them, with the team\'s total salary.',"SELECT m.name AS manager, COUNT(e.emp_id) AS reports, SUM(e.salary) AS team_salary\nFROM employees m\nJOIN employees e ON e.manager_id = m.emp_id\nGROUP BY m.emp_id, m.name\nORDER BY reports DESC;",'A self join where the left side is the manager and the right side is the reports.'),
(B,'Replace NULL department with the text "Unassigned" (COALESCE) and show string functions.',"SELECT name, COALESCE(CAST(dept_id AS TEXT), 'Unassigned') AS dept, UPPER(name) AS upper_name, LENGTH(name) AS len, SUBSTR(name, 1, 3) AS first3\nFROM employees WHERE emp_id IN (1, 10) ORDER BY emp_id;",'`COALESCE(a, b)` returns the first non-NULL argument. Names of string functions differ by database: `SUBSTR`/`SUBSTRING`, `LENGTH`/`LEN`, `||`/`CONCAT`.'),
]
db = sqlite3.connect(':memory:')
for t, cols, rows in schema:
    db.execute('create table %s (%s)' % (t, ', '.join(cols)))
    db.executemany('insert into %s values (%s)' % (t, ','.join('?' * len(cols))), rows)
out_items = []
for lvl, q, sql, exp in items:
    # an item may hold several statements; the displayed output is that of the first SELECT
    stmts = [s for s in sql.split(';') if s.strip() and not all(l.strip().startswith('--') or not l.strip() for l in s.split('\n'))]
    cur = db.execute(stmts[0].strip()); cols = [d[0] for d in cur.description]; rows = [list(r) for r in cur.fetchall()]
    # keep the whole text for display but verify only first statement (checked by the verify tool)
    out_items.append({'lvl': lvl, 'q': q, 'sql': stmts[0].strip() + ';' if len(stmts) == 1 else sql, 'out': {'cols': cols, 'rows': rows}, 'explain': exp})
# the verify tool runs item.sql as one statement, so keep one statement per item
for it in out_items:
    body = [s for s in it['sql'].split(';') if s.strip()]
    it['sql'] = it['sql'].split(';\n--')[0].rstrip(';').strip() + ';'
    it['sql'] = it['sql'].replace('\n-- page 2: ... ORDER BY salary DESC LIMIT 3 OFFSET 3', '')
js = 'IV.sql = ' + json.dumps({'schema': [{'table': t, 'cols': c, 'rows': [list(r) for r in rows]} for t, c, rows in schema], 'items': out_items}, indent=1, ensure_ascii=False) + ';\n'
p = os.path.join(os.path.dirname(__file__), '..', 'infosys-interview', 'data', 'sql.js')
open(p, 'w', encoding='utf-8').write(js)
print('items', len(out_items))
